 function checkBoredOblique(body){checkOblique(body,10,24);assert.equal(body.brep.vertices.length,16);assert.ok(body.hole_radius>0);assert.deepEqual(body.brep.wire_edges.slice(0,2).map(w=>w.length),[2,2]);const innerWires=body.brep.wire_edges.reduce((sum,w)=>sum+w.length-1,0);assert.equal(body.brep.vertices.length-body.brep.edges+body.brep.faces-innerWires,0,'actual genus-one Euler characteristic');assert.equal(body.mass_properties.ok,true);assert.ok(body.mass_properties.centroid.every(Number.isFinite));assert.ok(body.mass_properties.inertia.flat().every(Number.isFinite));boundedNumericParity(body.mass_properties.volume,body.volume,'actual bored oblique mass volume');assert.equal(body.step_exact,true);for(let i=0;i<body.mesh.positions.length;i++){const p=body.mesh.positions[i],n=body.mesh.normals[i];const local=p.map((x,j)=>x-body.placement.translation[j]),radial=body.placement.axes.slice(0,2).map(axis=>axis.reduce((sum,x,j)=>sum+x*local[j],0)),rad=Math.hypot(...radial);if(Math.abs(rad-body.hole_radius)<1e-6){const nd=body.placement.axes.slice(0,2).map(axis=>axis.reduce((sum,x,j)=>sum+x*n[j],0));if(Math.hypot(...nd)>.5)assert.ok(nd[0]*radial[0]+nd[1]*radial[1]<0,'actual inner cylindrical wall inward normal');}}}
