 function cylinderCutMasses(R,r,H,h,a){const A=Math.PI*(R*R-r*r),Q=Math.PI*(R**4-r**4)/4,lower={v:A*h,first:[-a*Q,0,(h*h*A+a*a*Q)/2],second:[[Q*h,0,-h*a*Q],[0,Q*h,0],[-h*a*Q,0,h**3*A/3+h*a*a*Q]]},parent={v:A*H,first:[0,0,A*H*H/2],second:[[Q*H,0,0],[0,Q*H,0],[0,0,A*H**3/3]]},upper={v:parent.v-lower.v,first:parent.first.map((x,i)=>x-lower.first[i]),second:parent.second.map((row,i)=>row.map((x,j)=>x-lower.second[i][j]))};return[lower,upper].map(m=>{const c=m.first.map(x=>x/m.v),central=m.second.map((row,i)=>row.map((x,j)=>x-m.v*c[i]*c[j])),trace=central.reduce((sum,row,i)=>sum+row[i],0);return{volume:m.v,centroid:c,inertia:central.map((row,i)=>row.map((x,j)=>(i===j?trace:0)-x))};});}
 function checkMassConservation(parts,parent){const masses=parts.map(b=>b.mass_properties),total=masses.reduce((s,m)=>s+m.volume,0);boundedNumericParity(total,parent.volume,'annular volume conservation');for(let i=0;i<3;i++)assert.ok(Math.abs(masses.reduce((sum,m)=>sum+m.volume*m.centroid[i],0)-parent.volume*parent.centroid[i])<1e-9*Math.max(1,parent.volume),'annular first moment conservation');const central=masses.map(m=>{const d=m.centroid.map((x,i)=>x-parent.centroid[i]),q=d.reduce((s,x)=>s+x*x,0);return m.inertia.map((row,i)=>row.map((x,j)=>x+m.volume*((i===j?q:0)-d[i]*d[j])));}),norm=Math.max(1,...parent.inertia.flat().map(Math.abs));for(let i=0;i<3;i++)for(let j=0;j<3;j++)assert.ok(Math.abs(central[0][i][j]+central[1][i][j]-parent.inertia[i][j])<2e-10*norm,'annular centroidal tensor conservation');}
 const beforeCut=structuredClone(boredPlaneDoc);beforeCut.operations.pop();beforeCut.output=beforeCut.operations.at(-1).id;const parentMassReport=await applyDocument(beforeCut);checkMassConservation(boredPlaneReport.components,parentMassReport.components[0].mass_properties);const annularCylinder=structuredClone(boredPlaneDoc);annularCylinder.operations[0].radii=[16,16];const cylinderParts=await applyDocument(annularCylinder),closedMasses=cylinderCutMasses(16,4,24,12,.2);for(let k=0;k<2;k++){const m=cylinderParts.components[k].mass_properties,expected=closedMasses[k];assert.ok(Math.abs(m.volume-expected.volume)<1e-8);for(let i=0;i<3;i++)assert.ok(Math.abs(m.centroid[i]-expected.centroid[i])<1e-9);const norm=Math.max(...expected.inertia.flat().map(Math.abs));for(let i=0;i<3;i++)for(let j=0;j<3;j++)assert.ok(Math.abs(m.inertia[i][j]-expected.inertia[i][j])<1e-10*norm,'independent tilted annular cylinder closed-form tensor');}const worldCylinder=structuredClone(annularCylinder);worldCylinder.operations[0].origin=[12,-5,8];worldCylinder.operations[0].axes=[[0,1,0],[0,0,1],[1,0,0]];worldCylinder.operations[2].origin=[24,-5,8];worldCylinder.operations[2].normal=[1,.2,0];const worldParts=await applyDocument(worldCylinder),permutation=[2,0,1];for(let k=0;k<2;k++){const m=worldParts.components[k].mass_properties,expected=closedMasses[k];for(let i=0;i<3;i++)assert.ok(Math.abs(m.centroid[i]-([12,-5,8][i]+expected.centroid[permutation[i]]))<1e-9);const norm=Math.max(...expected.inertia.flat().map(Math.abs));for(let i=0;i<3;i++)for(let j=0;j<3;j++)assert.ok(Math.abs(m.inertia[i][j]-expected.inertia[permutation[i]][permutation[j]])<1e-10*norm,'actual world-frame annular cylinder tensor');}await applyDocument(boredObliqueFixture);await page.locator('#component').selectOption('0');assert.match(await page.locator('#mass-status').textContent(),/Uniform density/);assert.doesNotMatch(await page.locator('#centroid').textContent(),/Unavailable/);

